    static void Main(string[] args)
    {
        const double Wavelength = 600e-9; // nm in Meter umrechnen
        const double SpeedOfLight = 299792458;

        // Berechnung der Planckschen Konstante (h) mittels Energie und Lichtgeschwindigkeit
        const double PlanckConstant = 6.62607004e-34;
        double photonEnergy = PlanckConstant * SpeedOfLight / Wavelength;
        double h = photonEnergy / SpeedOfLight;

        Console.WriteLine("Der Wert der Planckschen Konstante (h) lautet: " + h.ToString("F15") + " J s");
        Console.WriteLine("Die Energie eines Photons mit einer Wellenlänge von 600 nm lautet: " + photonEnergy.ToString("F15") + " J");
    }
}
```

