```java
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Predicate;

public class FlowerCategorizer {

    private final Map<String, ArrayList<String>> categories = new HashMap<>();

    public void categorizeFlowers(String[] flowerNames) {
        for (String flowerName : flowerNames) {
            String category = getFlowerCategory(flowerName);
            // Add or update list of flowers in the category
            categories.computeIfPresent(category, (k, v) -> {
                v.add(flowerName);
                return v;
            });
            categories.putIfAbsent(category, new ArrayList<>(List.of(flowerName)));
        }
    }

    private String getFlowerCategory(String flowerName) {
        Map<String, Predicate<String>> categoryPredicates = new HashMap<>();

        categoryPredicates.put("Lilac", flowerName -> flowerName.startsWith("Li"));
        categoryPredicates.put("Daisy", flowerName -> flowerName.startsWith("Da"));
        categoryPredicates.put("Marigold", flowerName -> flowerName.startsWith("Ma"));
        categoryPredicates.put("Chrysanthemum", flowerName -> flowerName.startsWith("Ch"));

        return categoryPredicates.entrySet().stream()
                .filter(entry -> entry.getValue().test(flowerName))
                .map(Map.Entry::getKey)
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException("Invalid flower name: " + flowerName));
    }

    public Map<String, ArrayList<String>> getCategories() {
        return categories;
    }
}
```

